import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/** One member of the roster. Provided -- do not edit. */
record RosterMember(int id, String name) { }

/**
 * TASK: Look members up by id with Collections.binarySearch and a custom
 * Comparator, not with a linear scan.
 *
 * The roster is always already sorted by ascending id. binarySearch needs a
 * "probe" object to compare against, so build one with the wanted id and any
 * name at all -- the Comparator only ever looks at the id:
 *     Comparator<RosterMember> byId = Comparator.comparingInt(RosterMember::id);
 *     int hit = Collections.binarySearch(roster, new RosterMember(id, ""), byId);
 *
 * indexOfId(roster, id): the index of the matching member, or -1 when absent.
 * insertionPointFor(roster, id): where the member WOULD go to keep the list
 *     sorted. binarySearch returns (-(insertion point) - 1) when it misses,
 *     so undo that; when the id is already present return its index.
 *
 * Example: roster ids [10, 20, 30]
 *   indexOfId(.., 20) -> 1     indexOfId(.., 25) -> -1
 *   insertionPointFor(.., 25) -> 2    insertionPointFor(.., 5) -> 0
 *   insertionPointFor(.., 99) -> 3    insertionPointFor(.., 20) -> 1
 */
public class RosterIndex {

    public static int indexOfId(List<RosterMember> roster, int id) {
        Comparator<RosterMember> byId = Comparator.comparingInt(RosterMember::id);
        int hit = Collections.binarySearch(roster, new RosterMember(id, ""), byId);
        return hit >= 0 ? hit : -1;
    }

    public static int insertionPointFor(List<RosterMember> roster, int id) {
        Comparator<RosterMember> byId = Comparator.comparingInt(RosterMember::id);
        int hit = Collections.binarySearch(roster, new RosterMember(id, ""), byId);
        return hit >= 0 ? hit : -hit - 1;
    }
}
